// Generate the documentation website from the canonical mqlite source.
// Usage: node tools/build.mjs [path-to-mqlite] [--check]
// --check compares every generated byte without writing files or publishing.
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Marked } from 'marked';
import { gfmHeadingId } from 'marked-gfm-heading-id';
import { sha256, loadTranslations, keepEnglishHeadingIds, checkNumericPair, translateHandwritten, translateAgentPrompt, localeLinks, languageLinks, languageSwitch, SITE_LANGUAGES } from './i18n.mjs';
import { DIAGRAM_ASSETS, loadConceptDiagrams, conceptDiagramRenderer } from './concept-diagrams.mjs';
import { loadExplanatoryFigures, findExplanatoryFigure, renderExplanatoryFigure } from './explanatory-figures.mjs';
import { sourceAgentFacts, checkAgentContract } from './agent-contract.mjs';
import { renderFacts } from './facts.mjs';
import { readReleaseTags, isReleaseTree } from './releases.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const site = resolve(here, '..');
const GH = 'https://github.com/mqlitehq/mqlite';
const GENERATED_MARKER = '<!-- Generated by tools/build.mjs; edit the canonical source. -->';

export const PAGES = [
  ['concepts.md', 'concepts.html', 'Concepts', 'Queues, topics, subscriptions, filters, and the full message lifecycle.'],
  ['internals.md', 'internals.html', 'Internals', 'SQLite, the single-writer model, fencing tokens, indexes, and crash recovery.'],
  ['api-reference.md', 'api.html', 'HTTP API reference', 'Every broker operation: requests, responses, errors, and limits.'],
  ['cli.md', 'cli.html', 'CLI reference', 'Run, produce, consume, and administer queues with the command-line client.'],
  ['access-keys.md', 'access-keys.html', 'Access keys', 'Issue, scope, rotate, expire, and revoke broker access keys at runtime.'],
  ['deployment.md', 'deployment.html', 'Deployment', 'Configure and run one broker with Docker, systemd, or remote Turso storage.'],
  ['observability.md', 'observability.html', 'Observability', 'Monitor broker health, queue state, delivery failures, and storage.'],
  ['observability-cloud.md', 'observability-cloud.html', 'Cloud monitoring', 'Connect authenticated broker metrics to existing collectors on Fly.io, Alibaba Cloud, Azure, or Kubernetes.'],
  ['operations.md', 'operations.html', 'Operations', 'Back up, restore, upgrade, and operate a single-broker deployment.'],
];
export const CORE_PAGES = [...PAGES];
PAGES.push(
  ['turso.md', 'turso.html', 'Turso / libSQL', 'Shared queue semantics, remote storage, concurrency and failure boundaries.'],
  ['retention.md', 'retention.html', 'Retention', 'Authorized deletion, replay retention and storage reclamation.'],
  ['benchmark.md', 'benchmark.html', 'Benchmarks', 'Measurement methods, historical results and workload-specific limits.'],
  ['conformance.md', 'conformance.html', 'Conformance', 'The normative queue invariants and the tests that enforce them.'],
  ['dependencies.md', 'dependencies.html', 'Dependencies', 'Compatibility floors, dependency pins and supported build toolchains.'],
  ['mcp.md', 'mcp.html', 'MCP', 'Connect an AI agent to the broker through the MCP server.'],
  ['examples.md', 'examples.html', 'Examples', 'Complete examples for embedded queues, transactional enqueue and remote clients.'],
);
export const BUNDLE_FILES = PAGES.map(([src]) => src);
export const GENERATED_FILES = [...PAGES.map(([, out]) => out), 'llms-full.txt', 'site-metadata.json', 'assets/highlight.min.js'];
export const ALL_GENERATED_FILES = [...GENERATED_FILES, ...PAGES.map(([, out]) => `zh-CN/${out}`), 'zh-CN/index.html', 'zh-CN/agents.html', 'zh-CN/llms.txt', 'zh-CN/llms-full.txt', ...DIAGRAM_ASSETS, 'index.html', 'agents.html', 'llms.txt'];
const ZH = {
  'Concepts': ['核心概念', '队列、主题、订阅、过滤器与完整的消息生命周期。'],
  'Internals': ['内部原理', 'SQLite、单写入者模型、隔离令牌、索引与崩溃恢复。'],
  'HTTP API reference': ['HTTP API 参考', '所有 broker 操作的请求、响应、错误与限制。'],
  'CLI reference': ['CLI 参考', '通过命令行运行、生产、消费和管理队列。'],
  'Access keys': ['访问密钥', '在运行期间签发、授权、轮换、设置过期时间和撤销 broker 访问密钥。'],
  'Deployment': ['部署', '使用 Docker、systemd 或远程 Turso 存储配置并运行单个 broker。'],
  'Observability': ['可观测性', '监测 broker 健康、队列状态、投递失败与存储。'],
  'Cloud monitoring': ['云端监控', '将经过身份验证的指标接入 Fly.io、阿里云、Azure 或 Kubernetes 中已有的采集系统。'],
  'Operations': ['运维', '单 broker 部署的备份、恢复、升级与日常运维。'],
  'Turso / libSQL': ['Turso / libSQL', '一致的队列语义，以及远程存储、并发和故障边界。'],
  'Retention': ['保留与回收', '经授权的删除、重放记录保留与存储空间回收。'],
  'Benchmarks': ['性能测试', '测量方法、历史结果以及特定负载下的限制。'],
  'Conformance': ['一致性规范', '队列必须满足的不变量，以及验证这些不变量的测试。'],
  'Dependencies': ['依赖与兼容性', '源码兼容下限、依赖版本固定策略与受支持的构建工具链。'],
  'MCP': ['MCP', '通过 MCP 服务器将 AI 代理连接到 broker。'],
  'Examples': ['使用示例', '嵌入式队列、同事务入队与远程客户端的完整示例。'],
};
export const HANDWRITTEN_RELEASE_FILES = ['index.html', 'agents.html', 'llms.txt'];

const read = (root, path) => readFileSync(resolve(root, path), 'utf8');
const requireValue = (condition, message) => {
  if (!condition) throw new Error(message);
};

export function sourceMetadata(mq, options = {}) {
  const versions = [...read(mq, 'internal/version/version.go').matchAll(/^const Version = "(\d+\.\d+\.\d+)"$/gm)];
  requireValue(versions.length === 1, 'cannot read the single source version constant');
  const changelog = read(mq, 'CHANGELOG.md');
  const unreleasedSection = /^## Unreleased[ \t]*\r?\n([\s\S]*?)(?=^## |(?![\s\S]))/m.exec(changelog)?.[1] ?? '';
  const hasUnreleasedNotes = unreleasedSection.replace(/<!--[\s\S]*?-->/g, '')
    .split('\n').some((line) => line.trim() && !/^\s*#{1,6}\s/.test(line));
  // Hermetic fixtures can supply a catalog. The CLI always reads existing tags
  // and tracked source, so a dated heading cannot publish a prepared release.
  const tags = options.releaseTags ?? readReleaseTags(mq);
  requireValue(Array.isArray(tags) || tags instanceof Set, 'invalid release tag catalog');
  const published = new Set(tags);
  const release = [...changelog.matchAll(/^## (v\d+\.\d+\.\d+(?:-rc\.\d+)?)\s+—\s+\d{4}-\d{2}-\d{2}(?:\s+\(([^)]+)\))?\s*$/gm)]
    .find(([, tag, status = '']) => published.has(tag) && !tag.includes('-') && !/\b(?:retracted|withdrawn|unsupported)\b/i.test(status));
  requireValue(release, 'CHANGELOG.md has no dated stable release heading with an available Git tag');
  const sourceIsReleaseTag = options.sourceIsReleaseTag ?? isReleaseTree(mq, release[1]);
  requireValue(typeof sourceIsReleaseTag === 'boolean', 'invalid source/release tree state');
  const hasUnreleasedChanges = hasUnreleasedNotes || !sourceIsReleaseTag || versions[0][1] !== release[1].slice(1);
  const routes = [...read(mq, 'wire/wire.go').matchAll(/^\s*Path\w+\s*=\s*"(\/mqlite\.v1\.[^"]+)"/gm)].map((m) => m[1]);
  const tools = [...read(mq, 'cmd/mqlite-mcp/main.go').matchAll(/^\s+name:\s+"([^"]+)"/gm)].map((m) => m[1]);
  const dispatch = /^\tswitch cmd \{([\s\S]*?)^\t\}/m.exec(read(mq, 'cmd/mqlite/main.go'))?.[1];
  requireValue(dispatch, 'cannot find the CLI command dispatch');
  const meta = new Set(['version', 'help', '-v', '--version', '-h', '--help', 'create-subscription']);
  const commands = [...new Set([...dispatch.matchAll(/^\s*case ([^:]+):/gm)].flatMap((m) => [...m[1].matchAll(/"([^"]+)"/g)].map((s) => s[1])))].filter((name) => !meta.has(name));
  for (const [name, values] of Object.entries({ routes, tools, commands })) {
    requireValue(values.length >= 5 && new Set(values).size === values.length, `invalid ${name} source contract`);
  }
  return {
    ...sourceAgentFacts(mq),
    sourceVersion: versions[0][1],
    latestRelease: release[1],
    hasUnreleasedChanges,
    source: `${GH}/tree/main/docs`,
    routes: routes.sort(),
    mcpTools: tools.sort(),
    cliCommands: commands.sort(),
    documents: BUNDLE_FILES,
    generatedFiles: ALL_GENERATED_FILES,
    locales: SITE_LANGUAGES.map(({ tag }) => tag),
    defaultLocale: 'en',
  };
}

export function rewriteLinks(html) {
  return html.replace(/href="([^"]+)"/g, (match, href) => {
    if (/^(https?:|#|mailto:)/.test(href)) return match;
    const [path, frag = ''] = href.split('#');
    const anchor = frag ? `#${frag}` : '';
    const mapped = PAGES.find(([src, out]) => path === src || path === out)?.[1];
    if (mapped) return `href="${mapped}${anchor}"`;
    if (path.startsWith('../')) return `href="${GH}/blob/main/${path.slice(3)}${anchor}"`;
    return `href="${GH}/blob/main/docs/${path}${anchor}"`;
  });
}

export function rewriteMdLinks(md, chinese = false) {
  const parser = new Marked({ gfm: true });
  const literals = new Set();
  parser.walkTokens(parser.lexer(md), (token) => {
    if (token.type === 'codespan') literals.add(token.raw);
    if (token.type === 'code') {
      literals.add(token.raw);
      // Nested fenced blocks can have quote/list prefixes removed by the lexer.
      // Their individual code lines still occur literally in the source.
      for (const line of token.text.split('\n')) if (line) literals.add(line);
    }
  });
  const protectedRanges = [];
  for (const literal of literals) {
    let start = md.indexOf(literal);
    while (start !== -1) {
      protectedRanges.push([start, start + literal.length]);
      start = md.indexOf(literal, start + literal.length);
    }
  }
  return md.replace(/\]\(([^)\s]+)\)/g, (match, href, offset) => {
    if (protectedRanges.some(([start, end]) => offset >= start && offset + match.length <= end)) return match;
    if (/^(https?:|#|mailto:)/.test(href)) return match;
    const [path, frag = ''] = href.split('#');
    const anchor = frag ? `#${frag}` : '';
    const local = PAGES.find(([src]) => path === src)?.[1];
    if (chinese && local) return `](https://mqlitehq.github.io/zh-CN/${local}${anchor})`;
    return `](${GH}/blob/main/${path.startsWith('../') ? path.slice(3) : `docs/${path}`}${anchor})`;
  });
}

export function localizeSummary(summary) {
  // Navigation opens the matching locale; the explicitly labelled source section
  // continues to point to canonical English Markdown and published artifacts.
  const [navigation, ...source] = summary.split('\n## 源码\n');
  const localized = navigation
    .replace('<https://mqlitehq.github.io/>', '<https://mqlitehq.github.io/zh-CN/>')
    .replace(/\]\(https:\/\/github\.com\/mqlitehq\/mqlite\/blob\/main\/docs\/([^)]+)\)/g, (all, file) => {
      const out = PAGES.find(([src]) => src === file)?.[1];
      return out ? `](${out})` : all;
    });
  return [localized, ...source].join('\n## 源码\n');
}

function page({ title, description, src, out, body }, metadata, chinese = false) {
  const unreleased = metadata.hasUnreleasedChanges || metadata.latestRelease !== `v${metadata.sourceVersion}`;
  const sourceStatus = chinese
    ? `源码 v${metadata.sourceVersion}${unreleased ? '（含未发布变更）' : ''}`
    : `source v${metadata.sourceVersion}${unreleased ? ' with unreleased changes' : ''}`;
  const localTitle = chinese ? ZH[title][0] : title;
  const localDescription = chinese ? ZH[title][1] : description;
  const navLabel = (label) => label === 'HTTP API reference' ? 'API' : label === 'CLI reference' ? 'CLI' : chinese ? ZH[label][0] : label;
  const navigation = CORE_PAGES.map(([pageSrc, output, label]) => `    <a href="${output}"${pageSrc === src ? ' aria-current="page"' : ''}>${navLabel(label)}</a>`).join('\n');
  const current = CORE_PAGES.some(([name]) => name === src) ? '' : `<a class="document-label" href="${out}" aria-current="page">${localTitle}</a> · `;
  const stamp = chinese
    ? `${current}来源：<a href="${GH}/blob/main/docs/${src}">mqlite main · docs/${src}</a> — ${sourceStatus}。最新受支持版本：<a href="${GH}/releases/tag/${metadata.latestRelease}">${metadata.latestRelease}</a>。本文档跟随 main；使用已发布产物时，请查阅对应版本的文档。`
    : `${current}Source: <a href="${GH}/blob/main/docs/${src}">mqlite main · docs/${src}</a> — ${sourceStatus}. Latest supported release: <a href="${GH}/releases/tag/${metadata.latestRelease}">${metadata.latestRelease}</a>. These docs track main; use the linked release for published artifacts.`;
  const html = `<!doctype html>
${GENERATED_MARKER}
<html lang="${chinese ? 'zh-CN' : 'en'}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${localTitle} · mqlite</title>
<meta name="description" content="${localDescription}">
${languageLinks(out, chinese)}
<link rel="icon" href="favicon.svg" type="image/svg+xml">
<link rel="stylesheet" href="assets/site.css">
<script src="assets/highlight.min.js" defer></script>
<script src="assets/site.js" defer></script>
</head>
<body>
<nav class="top" aria-label="${chinese ? '主导航' : 'Main navigation'}"><div class="wrap">
  <a class="brand" href="./"><img src="logo.svg" alt="" width="24" height="24"> mqlite</a>
  <div class="links overflow-nav" data-overflow>
    <div class="overflow-primary"></div>
    ${languageSwitch(out, chinese)}
    <details class="overflow-more has-current" name="header-menu">
      <summary aria-label="${chinese ? '更多导航链接' : 'More navigation links'}">${chinese ? '更多' : 'More'}</summary>
      <div class="overflow-items">
${navigation}
    <a href="agents.html">${chinese ? 'AI 代理指南' : 'For AI agents'}</a>
    <a class="gh" href="${GH}">GitHub ↗</a>
      </div>
    </details>
  </div>
</div></nav>
<div class="wrap">
  <div class="stamp">${stamp}</div>
  <main class="prose">
${body}
  </main>
</div>
<footer class="site"><div class="wrap">
  <span>MIT © The MQLite Authors</span>
  <a href="${GH}">GitHub</a>
  <a href="${GH}/releases">${chinese ? '版本发布' : 'Releases'}</a>
  <a href="llms.txt">llms.txt</a>
</div></footer>
</body>
</html>
`;
  return localeLinks(html, chinese);
}

export function renderSite(mq, options = {}) {
  const bilingual = options.bilingual !== false;
  const metadata = sourceMetadata(mq, options);
  if (!bilingual) metadata.generatedFiles = GENERATED_FILES;
  if (bilingual) metadata.agentGuideContract = checkAgentContract(options.translationRoot ?? site, mq);
  const translations = bilingual ? loadTranslations(options.translationRoot ?? site, mq, BUNDLE_FILES) : null;
  if (bilingual) requireValue(translations.manifest.chromeSourceSha256 === sha256(JSON.stringify(PAGES)), 'page titles or descriptions changed; review Chinese chrome');
  const marked = new Marked({ gfm: true });
  marked.use(gfmHeadingId());
  const diagrams = bilingual ? loadConceptDiagrams(read(mq, 'docs/concepts.md')) : null;
  const explanations = bilingual ? loadExplanatoryFigures(new Map(PAGES.map(([source]) => [source, read(mq, `docs/${source}`)]))) : [];
  const parse = (markdown, source, chinese = false) => {
    if (!diagrams) return marked.parse(markdown);
    const illustrated = new Marked({ gfm: true });
    const concepts = conceptDiagramRenderer(source === 'concepts.md' ? diagrams : [], chinese);
    const figures = explanations.filter((record) => record.file === source);
    illustrated.use(gfmHeadingId(), { renderer: { code(token) {
      const figure = findExplanatoryFigure(figures, token);
      return figure ? renderExplanatoryFigure(figure, chinese) : concepts.code(token);
    } } });
    return illustrated.parse(markdown);
  };
  const outputs = new Map();
  for (const [src, out, title, description] of PAGES) {
    const english = parse(read(mq, `docs/${src}`), src);
    const body = rewriteLinks(english);
    outputs.set(out, page({ title, description, src, out, body }, metadata));
  }
  const releaseURL = `${GH}/releases/tag/${metadata.latestRelease}`;
  const parts = BUNDLE_FILES.map((file) => `<!-- ===== mqlite main · source v${metadata.sourceVersion}; latest supported release ${metadata.latestRelease} · docs/${file} ===== -->\n\n${rewriteMdLinks(read(mq, `docs/${file}`))}`);
  const sourceStatus = metadata.hasUnreleasedChanges || metadata.latestRelease !== `v${metadata.sourceVersion}`
    ? 'Source includes unreleased changes.\n' : '';
  outputs.set('llms-full.txt', `mqlite main — full documentation bundle.\nSource version: v${metadata.sourceVersion}. Latest supported release: [${metadata.latestRelease}](${releaseURL}).\n${sourceStatus}These docs track main; consult release notes for published artifacts and upgrade requirements.\nSource of truth: ${metadata.source}\n\n${parts.join('\n\n')}`);
  outputs.set('site-metadata.json', `${JSON.stringify(metadata, null, 2)}\n`);
  outputs.set('assets/highlight.min.js', readFileSync(resolve(here, 'node_modules/@highlightjs/cdn-assets/highlight.min.js')));
  if (bilingual) {
    for (const [src, out, title, description] of PAGES) {
      const en = parse(read(mq, `docs/${src}`), src);
      const zh = keepEnglishHeadingIds(en, parse(translations.documents.get(src), src, true), src);
      outputs.set(`zh-CN/${out}`, page({ title, description, src, out, body: rewriteLinks(zh) }, metadata, true));
    }
    for (const name of ['index.html', 'agents.html']) {
      const english = read(options.translationRoot ?? site, `templates/${name}`);
      let chinese = translateHandwritten(english, translations.interface, name);
      if (name === 'index.html') chinese = chinese.replace('src="assets/fig-overview.svg"', 'src="assets/zh-CN/fig-overview.svg"');
      if (name === 'agents.html') chinese = translateAgentPrompt(chinese, translations.prompt);
      checkNumericPair(english, chinese, name);
      chinese = chinese.replace('<html lang="en">', '<html lang="zh-CN">')
        .replace(/<details\b[^>]*data-language-picker[^>]*>[\s\S]*?<\/details>/, languageSwitch(name, true))
        .replace(/<link rel="alternate"[^>]*>\n?/g, '');
      chinese = chinese.replace('</head>', `${languageLinks(name, true)}\n</head>`);
      outputs.set(`zh-CN/${name}`, renderFacts(localeLinks(chinese, true), metadata, true));
    }
    outputs.set('zh-CN/llms.txt', renderFacts(localizeSummary(translations.summary), metadata, true));
    const zhParts = BUNDLE_FILES.map((file) => `<!-- ===== docs/${file} · 英文与简体中文逐项对应 ===== -->\n\n${rewriteMdLinks(translations.documents.get(file), true)}`);
    outputs.set('zh-CN/llms-full.txt', `mqlite main — 完整简体中文文档。\n源码版本：v${metadata.sourceVersion}。最新受支持版本：[${metadata.latestRelease}](${releaseURL})。\n${sourceStatus ? '源码包含未发布变更。\n' : ''}本文档跟随 main；使用已发布产物时，请核对相应版本说明。\n英文规范来源：${metadata.source}\n\n${zhParts.join('\n\n')}`);
    for (const diagram of diagrams) outputs.set(diagram.asset, diagram.svg);
    for (const diagram of diagrams) outputs.set(diagram.chineseAsset, diagram.chineseSvg);
    for (const name of HANDWRITTEN_RELEASE_FILES) {
      outputs.set(name, renderFacts(read(options.translationRoot ?? site, `templates/${name}`), metadata));
    }
  }
  requireValue(JSON.stringify([...outputs.keys()]) === JSON.stringify(bilingual ? ALL_GENERATED_FILES : GENERATED_FILES), 'generated output inventory drift');
  return { outputs, metadata };
}

export function checkOutputs(outputs, root = site) {
  for (const [file, expected] of outputs) {
    let actual;
    try {
      actual = readFileSync(resolve(root, file));
    } catch {
      throw new Error(`missing generated output: ${file}`);
    }
    requireValue(actual.equals(Buffer.from(expected)), `stale generated output: ${file}`);
  }
  for (const file of htmlFiles(root)) {
    requireValue(!read(root, file).includes(GENERATED_MARKER) || outputs.has(file), `obsolete generated output: ${file}`);
  }
}

export function checkClaims(metadata, root = site) {
  const counts = { routes: metadata.routes.length, tools: metadata.mcpTools.length, commands: metadata.cliCommands.length };
  const seen = new Set();
  for (const file of readdirSync(root).filter((name) => /\.(html|txt)$/.test(name))) {
    const text = read(root, file);
    const visible = text.replace(/<[^>]*>/g, '').replace(/\*\*/g, '').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
    for (const match of visible.matchAll(/\b(\d+) (?:(?:RPC|MCP|CLI) )?(routes|tools|commands)\b/g)) {
      requireValue(Number(match[1]) === counts[match[2]], `${file}: stale ${match[2]} count ${match[1]} (expected ${counts[match[2]]})`);
      seen.add(match[2]);
    }
    for (const match of visible.matchAll(/(?:latest(?: (?:recorded|published|supported))? release|newest RELEASE)(?::| is)?\s*(v\d+\.\d+\.\d+(?:-rc\.\d+)?)/gi)) {
      requireValue(match[1] === metadata.latestRelease, `${file}: incorrect latest release ${match[1]}`);
    }
    requireValue(!text.includes('mqlitehq.github.io/blob/'), `${file}: private site source link`);
    for (const line of text.split('\n').filter((line) => line.includes('8080') && metadata.brokerPort !== '8080')) {
      requireValue(/0\.2/.test(line), `${file}: legacy port 8080 requires an explicit 0.2 release context`);
    }
  }
  requireValue(Object.keys(counts).every((key) => seen.has(key)), 'site is missing a source-derived API/MCP/CLI count');
  const source = `v${metadata.sourceVersion}`;
  const latest = metadata.latestRelease;
  const escape = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const releaseStatus = new RegExp(
    `(?:unreleased.{0,160}(?:source\\s+)?${escape(source)}|(?:source\\s+)?${escape(source)}.{0,160}unreleased)`,
    'i',
  );
  for (const file of HANDWRITTEN_RELEASE_FILES) {
    requireValue(existsSync(resolve(root, file)), `${file}: missing hand-written release facts`);
    for (const [command] of read(root, file).matchAll(/\bgo (?:install|get) [^\n<`]+/g)) {
      for (const [, query] of command.matchAll(/github\.com\/mqlitehq\/(?:mqlite-go|mqlite)(?:\/[\w./-]+)?@([^\s<`]+)/g)) {
        requireValue(query === 'latest', `${file}: current installation commands must use @latest, not ${query}`);
      }
    }
    const visible = read(root, file).replace(/<[^>]*>/g, '').replace(/\*\*/g, '').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
    const sourceClaims = [...visible.matchAll(/\bsource\s+(v\d+\.\d+\.\d+(?:-rc\.\d+)?)\b/gi)];
    requireValue(sourceClaims.length > 0, `${file}: missing source version ${source}`);
    for (const match of sourceClaims) {
      requireValue(match[1] === source, `${file}: incorrect source version ${match[1]} (expected ${source})`);
    }
    requireValue(
      new RegExp(`\\blatest supported release(?::| is)?\\s+${escape(latest)}\\b`, 'i').test(visible),
      `${file}: missing latest supported release ${latest}`,
    );
    const expectedUnreleased = metadata.hasUnreleasedChanges || latest !== source;
    requireValue(
      releaseStatus.test(visible) === expectedUnreleased,
      `${file}: source ${source} must be described as ${expectedUnreleased ? 'unreleased' : 'released'}`,
    );
  }
  const bundle = read(root, 'llms-full.txt');
  requireValue(!/\]\((\.\.\/|[a-z0-9_-]+\.md)/.test(bundle), 'llms-full.txt has relative source links');
}

export function checkLinks(root = site) {
  for (const file of [...htmlFiles(root), 'llms.txt', ...(existsSync(resolve(root, 'zh-CN/llms.txt')) ? ['zh-CN/llms.txt'] : [])]) {
    const text = read(root, file);
    const references = file.endsWith('.html') ? text.matchAll(/(?:href|src)="([^"]+)"/g) : text.matchAll(/\]\(([^)\s]+)\)/g);
    for (const [, href] of references) {
      if (/^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(href)) continue;
      const url = new URL(href, `https://preview.invalid/${file}`);
      const target = decodeURIComponent(url.pathname.slice(1)) || 'index.html';
      const path = resolve(root, target.endsWith('/') ? `${target}index.html` : target);
      requireValue(existsSync(path), `${file}: missing local link ${href}`);
      if (url.hash && path.endsWith('.html')) {
        const ids = [...readFileSync(path, 'utf8').matchAll(/id="([^"]+)"/g)].map((m) => m[1]);
        requireValue(ids.includes(decodeURIComponent(url.hash.slice(1))), `${file}: missing local anchor ${href}`);
      }
    }
  }
}

function htmlFiles(root, prefix = '') {
  return readdirSync(resolve(root, prefix), { withFileTypes: true }).flatMap((item) => item.isFile() && item.name.endsWith('.html') ? [prefix + item.name] : item.isDirectory() && item.name === 'zh-CN' ? htmlFiles(root, prefix + item.name + '/') : []);
}

function main() {
  const args = process.argv.slice(2);
  const check = args.includes('--check');
  const paths = args.filter((arg) => arg !== '--check');
  requireValue(paths.length <= 1 && paths.every((arg) => !arg.startsWith('--')), 'usage: node tools/build.mjs [path-to-mqlite] [--check]');
  const mq = resolve(here, paths[0] ?? '../../mqlite');
  const { outputs, metadata } = renderSite(mq);
  if (!check) {
    for (const [file, content] of outputs) {
      mkdirSync(dirname(resolve(site, file)), { recursive: true });
      writeFileSync(resolve(site, file), content);
    }
  }
  checkOutputs(outputs);
  checkClaims(metadata);
  checkLinks();
  console.log(`${check ? 'Verified' : 'Generated'} ${outputs.size} outputs: source v${metadata.sourceVersion}, latest release ${metadata.latestRelease}; ${metadata.routes.length} routes, ${metadata.mcpTools.length} tools, ${metadata.cliCommands.length} commands.`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
